"""AURION ONE: integrated local agent UI; reuses existing authenticated API."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

@router.get('/one', response_class=HTMLResponse)
async def one_panel():
    return r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AURION ONE | Agente</title><style>
:root{color-scheme:dark;font:16px system-ui}*{box-sizing:border-box}body{margin:0;background:#061326;color:#edf6ff}header{padding:18px 22px;background:#0b2444;border-bottom:1px solid #2767a0;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}h1{font-size:1.25rem;margin:0}h2{font-size:1.05rem}small,.muted{color:#b1c5dc}main{max-width:1100px;margin:auto;padding:16px;display:grid;grid-template-columns:1fr 1.5fr;gap:14px}.card{border:1px solid #275783;border-radius:14px;background:#102744;padding:16px;min-width:0}.wide{grid-column:1/-1}button,input,textarea{font:inherit;border-radius:9px;padding:11px;border:1px solid #4380b6;color:white;background:#0a1c33}button{background:#185eaa;cursor:pointer}button:disabled{opacity:.5;cursor:wait}input,textarea{width:100%}textarea{resize:vertical}.status{display:flex;justify-content:space-between;gap:8px;padding:9px 0;border-bottom:1px solid #274464}.on{color:#77e4aa}.off{color:#ffc18b}.unknown{color:#c2cbd8}#messages{height:360px;overflow:auto;display:flex;flex-direction:column;gap:10px;padding:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}.bubble{padding:12px;border-radius:12px;background:#1a395a;max-width:94%;align-self:flex-start}.mine{background:#184e86;align-self:flex-end}.error{border:1px solid #d08a58}.danger{border:2px solid #e5484d;background:#2a1016;box-shadow:0 0 0 1px #7f1d27 inset}.danger h2{color:#ff7378}.danger button{background:#a61f2b;border-color:#ff5a63}.danger input[type=file]{border-color:#d9464f;background:#170b0e}.danger .warning{color:#ffb4b7}.vault-row{padding:8px 0;border-bottom:1px solid #68303a}.c4d-card{border-color:#ff8a24;background:#21150c}.c4d-card h2{color:#ffad5c}.c4d-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.c4d-box{background:#100e0b;border:1px solid #70431e;border-radius:10px;padding:10px;min-width:0}.c4d-box h3{margin:0 0 8px;font-size:.95rem;color:#ffd0a3}.c4d-box pre{margin:0;max-height:280px}.c4d-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.c4d-actions button{background:#a64b00;border-color:#ff8a24;width:auto}@media(max-width:720px){.c4d-grid{grid-template-columns:1fr}}.blender-card{border-color:#39c5bb;background:#071d20}.blender-card h2{color:#69efe5}.blender-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.blender-tabs button{background:#0d5960;border-color:#39c5bb;width:auto}.blender-tabs button.active{background:#168894}.blender-panel{display:none;background:#061417;border:1px solid #21686b;border-radius:10px;padding:12px}.blender-panel.active{display:block}.blender-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.blender-row{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.blender-row>*{flex:1;min-width:150px}.blender-card pre{background:#031013;border:1px solid #174d50;border-radius:8px;padding:10px}.blender-card label{display:block;color:#b9e7e4;font-size:.85rem;margin:6px 0}.blender-card select{width:100%;font:inherit;border-radius:9px;padding:11px;border:1px solid #4380b6;color:white;background:#0a1c33}@media(max-width:720px){.blender-grid{grid-template-columns:1fr}}form{display:flex;gap:8px;align-items:end}form textarea{flex:1}form button{width:auto}#auth{display:flex;gap:8px}#auth input{max-width:320px}#auth button{white-space:nowrap}a{color:#8bc6ff}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:250px;overflow:auto} @media(max-width:720px){main{grid-template-columns:1fr}.wide{grid-column:auto}header{align-items:stretch}#auth{width:100%}#auth input{min-width:0;flex:1}form{align-items:stretch;flex-direction:column}}
</style></head><body><header><div><h1>AURION ONE · agente local</h1><small>Respostas reais do Ollama; sem simular conexões</small></div><div id="auth"><input id="token" type="password" autocomplete="off" placeholder="Token local AURION" aria-label="Token local"><button id="connect">Conectar</button></div></header><main><section class="card"><h2>Conexões verificadas</h2><div class="status">Portal <strong id="portal" class="unknown">verificando</strong></div><div class="status">Ollama <strong id="ollama" class="unknown">aguardando autenticação</strong></div><div class="status">ComfyUI <strong id="comfy" class="unknown">não verificado</strong></div><div class="status">POCO <strong id="poco" class="unknown">não verificado</strong></div><div class="status">Drive / ChatGPT / Gemini <strong class="unknown">não conectados neste painel</strong></div><p class="muted" id="notice">O token fica apenas nesta sessão do navegador. Use a chave do arquivo .env local; não a envie no chat.</p><button id="refresh">Atualizar estado</button></section><section class="card"><h2>Chat integrado · AURION</h2><div id="messages" role="log" aria-live="polite"><div class="bubble">Conecte o token para conversar com o agente local. Nenhum comando do PC é executado pelo chat.</div></div><form id="chat"><textarea id="message" rows="3" maxlength="12000" placeholder="Escreva para o agente..." required></textarea><button id="send" type="submit">Enviar</button></form><small>O agente usa o endpoint /api/prompt e o modelo configurado no servidor. Uma resposta não significa que uma tarefa foi executada.</small></section><section class="card wide c4d-card" id="c4dDiagnostics"><h2>ABA · DIAGNÓSTICO C4D & OCTANE EM TEMPO REAL</h2><p class="muted">Leitura local de processo, plugins, versões, preferências e BugReport. O monitor não altera nem apaga arquivos.</p><div class="c4d-actions"><button id="c4dRefresh" type="button">ATUALIZAR AGORA</button><button id="c4dLaunch" type="button">ABRIR CINEMA 4D</button><button id="c4dMonitor" type="button">MONITOR: LIGAR</button><button id="c4dOpenPlugin" type="button">ABRIR PASTA DO PLUGIN</button><button id="c4dOpenBug" type="button">ABRIR BUGREPORT</button></div><div class="c4d-grid"><div class="c4d-box"><h3>ESTADO</h3><pre id="c4dState">Aguardando autenticação.</pre></div><div class="c4d-box"><h3>CAMINHOS REAIS</h3><pre id="c4dPaths">—</pre></div><div class="c4d-box"><h3>ERROS CAPTADOS</h3><pre id="c4dErrors">—</pre></div><div class="c4d-box"><h3>SOLUÇÕES APONTADAS</h3><pre id="c4dSolutions">—</pre></div><div class="c4d-box wide"><h3>AÇÕES REGISTRADAS</h3><pre id="c4dActionsLog">—</pre></div></div></section><section class="card wide blender-card" id="blenderStudio"><h2>BLENDER 5.2 · ESTÚDIO 3D INTEGRADO</h2><p class="muted">Instalação alvo: C:\\Program Files\\Blender Foundation\\Blender 5.2. Controle local, render em segundo plano, bibliotecas e logs sem sair do painel.</p><div class="blender-row"><button id="blenderSetup" type="button">PREPARAR WORKSPACE</button><button id="blenderLaunch" type="button">ABRIR BLENDER</button><button id="blenderRefresh" type="button">ATUALIZAR ESTADO</button><button id="blenderMonitor" type="button">MONITOR: LIGAR</button></div><div class="blender-tabs"><button class="active" data-blender-tab="blenderOverview">VISÃO GERAL</button><button data-blender-tab="blenderRender">RENDER</button><button data-blender-tab="blenderNodes">NODES</button><button data-blender-tab="blenderTextures">TEXTURAS</button><button data-blender-tab="blenderRig">RIG</button><button data-blender-tab="blenderClothes">ROUPAS & ACESSÓRIOS</button></div><div id="blenderOverview" class="blender-panel active"><div class="blender-grid"><div><h3>ESTADO REAL</h3><pre id="blenderState">Aguardando autenticação.</pre></div><div><h3>CAMINHOS E CONTAGENS</h3><pre id="blenderPaths">—</pre></div></div><h3>AÇÕES REGISTRADAS</h3><pre id="blenderActions">—</pre></div><div id="blenderRender" class="blender-panel"><h3>RENDER EM SEGUNDO PLANO</h3><label>Projeto .blend no PC</label><input id="blenderBlendFile" placeholder="C:\\Projetos\\cena.blend"><div class="blender-row"><div><label>Modo</label><select id="blenderRenderMode"><option value="still">Imagem</option><option value="animation">Animação</option></select></div><div><label>Frame</label><input id="blenderFrame" type="number" min="0" value="1"></div><div><label>Nome de saída</label><input id="blenderOutputName" value="aurion_render"></div></div><div class="blender-row"><button id="blenderStartRender" type="button">INICIAR RENDER</button><button data-blender-open="renders" type="button">ABRIR RENDERS</button><button data-blender-open="logs" type="button">ABRIR LOGS</button></div><pre id="blenderRenderLog">Nenhum render iniciado nesta sessão.</pre></div><div id="blenderNodes" class="blender-panel"><h3>NODES</h3><p>Biblioteca independente para arquivos .blend, receitas JSON e shaders OSL. Use este espaço para materiais, Geometry Nodes, compositor e grupos reutilizáveis.</p><button data-blender-open="nodes" type="button">ABRIR BIBLIOTECA DE NODES</button><pre id="blenderNodesList">—</pre></div><div id="blenderTextures" class="blender-panel"><h3>TEXTURAS</h3><p>Organização de mapas Base Color, Roughness, Metallic, Normal, Displacement, Alpha, HDRI e EXR.</p><button data-blender-open="textures" type="button">ABRIR BIBLIOTECA DE TEXTURAS</button><pre id="blenderTexturesList">—</pre></div><div id="blenderRig" class="blender-panel"><h3>RIG & ANIMAÇÃO</h3><p>Biblioteca para armatures, poses, FBX, GLTF/GLB e BVH. Os arquivos originais não são alterados pelo painel.</p><button data-blender-open="rigs" type="button">ABRIR BIBLIOTECA DE RIGS</button><pre id="blenderRigsList">—</pre></div><div id="blenderClothes" class="blender-panel"><h3>ROUPAS & ACESSÓRIOS</h3><p>Catálogo para roupas, tecidos, calçados, objetos e acessórios em BLEND, FBX, OBJ, GLTF, Alembic e USD.</p><button data-blender-open="clothes" type="button">ABRIR BIBLIOTECA DE ROUPAS</button><pre id="blenderClothesList">—</pre></div></section><section class="card wide danger" id="manualVault"><h2>ÁREA VERMELHA · IMPORTAÇÃO MANUAL EM QUARENTENA</h2><p class="warning">Selecione arquivos locais para inventário seguro. O painel calcula SHA-256, registra nome e tamanho e nunca executa o conteúdo. Arquivos associados a credenciais, licença ou ativação são somente inventariados e descartados; pacotes comuns ficam renomeados em quarentena aguardando validação.</p><input id="vaultFiles" type="file" multiple aria-label="Selecionar arquivos para quarentena"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button id="vaultUpload" type="button">CARREGAR NA QUARENTENA</button><button id="vaultRefresh" type="button">ATUALIZAR INVENTÁRIO</button></div><pre id="vaultResults">Nenhum arquivo carregado nesta sessão.</pre></section><section class="card wide"><h2>Diagnóstico e inventário</h2><button id="inventoryButton">Ler inventário salvo</button><pre id="inventory">Nenhum scan novo será iniciado automaticamente.</pre><p class="muted">Imagem, vídeo e reparo automático ainda não estão implementados neste painel. Não serão mostrados como ativos.</p></section></main><script>
'use strict';const $=id=>document.getElementById(id);let key=sessionStorage.getItem('aurion_one_session_token')||localStorage.getItem('aurion_token')||'';$('token').value=key;const set=(id,value,cls)=>{const e=$(id);e.textContent=value;e.className=cls};const note=s=>$('notice').textContent=s;async function api(path,opts={}){if(!key)throw Error('Informe o token local.');const r=await fetch(path,{...opts,headers:{...(opts.headers||{}),Authorization:'Bearer '+key}});let data;try{data=await r.json()}catch{throw Error('Resposta inválida do servidor ('+r.status+')')}if(!r.ok)throw Error(data.detail||'HTTP '+r.status);return data}async function status(){try{const r=await fetch('/health',{cache:'no-store'});set('portal',r.ok?'online':'erro',r.ok?'on':'off')}catch{set('portal','offline','off')}if(!key){set('ollama','sem token','unknown');return}try{const s=await api('/api/status');set('ollama',s.ollama==='online'?'online':'offline',s.ollama==='online'?'on':'off');const devices=Array.isArray(s.devices)?s.devices:[];set('poco',devices.some(d=>/poco/i.test(String(d.device_id||'')))?'registrado (não garante conexão atual)':'não verificado','unknown');note('Estado consultado no servidor. ComfyUI não possui verificação nesta API.')}catch(e){set('ollama','não verificado','unknown');note('Falha na autenticação/estado: '+e.message)}}function bubble(text,mine=false,error=false){const d=document.createElement('div');d.className='bubble'+(mine?' mine':'')+(error?' error':'');d.textContent=text;$('messages').append(d);$('messages').scrollTop=$('messages').scrollHeight;return d}$('connect').onclick=async()=>{key=$('token').value.trim();if(!key){note('Informe a chave local.');return}try{await api('/api/status');sessionStorage.setItem('aurion_one_session_token',key);note('Token validado para esta sessão.');await status()}catch(e){note('Não conectado: '+e.message)}};$('refresh').onclick=status;let c4dTimer=null;function renderC4D(s){$('c4dState').textContent=JSON.stringify({process:s.process,cinema4d:s.cinema4d,octane:s.octane,checked_at:s.checked_at},null,2);$('c4dPaths').textContent=JSON.stringify(s.paths,null,2);$('c4dErrors').textContent=(s.errors||[]).join('\n')||'Nenhum erro reconhecido no trecho atual.';$('c4dSolutions').textContent=(s.solutions||[]).map((x,i)=>(i+1)+'. '+x).join('\n')||'Nenhuma correção sugerida.';$('c4dActionsLog').textContent=(s.actions||[]).join('\n')||'Nenhuma ação registrada.'}async function refreshC4D(){if(!key){$('c4dState').textContent='Conecte o token primeiro.';return}try{renderC4D(await api('/api/c4d/status'))}catch(e){$('c4dState').textContent='Falha: '+e.message}}function toggleC4DMonitor(){if(c4dTimer){clearInterval(c4dTimer);c4dTimer=null;$('c4dMonitor').textContent='MONITOR: LIGAR'}else{refreshC4D();c4dTimer=setInterval(refreshC4D,5000);$('c4dMonitor').textContent='MONITOR: LIGADO'}}async function c4dAction(path){try{const r=await api(path,{method:'POST'});$('c4dActionsLog').textContent=JSON.stringify(r,null,2);setTimeout(refreshC4D,1200)}catch(e){$('c4dActionsLog').textContent='Falha: '+e.message}}$('c4dRefresh').onclick=refreshC4D;$('c4dMonitor').onclick=toggleC4DMonitor;$('c4dLaunch').onclick=()=>c4dAction('/api/c4d/launch');$('c4dOpenPlugin').onclick=()=>c4dAction('/api/c4d/open?target=plugin');$('c4dOpenBug').onclick=()=>c4dAction('/api/c4d/open?target=bugreport');let blenderTimer=null;function blenderItems(items){return (items||[]).map(x=>x.name+'\n  '+x.path).join('\n')||'Nenhum arquivo catalogado.'}function renderBlender(s){$('blenderState').textContent=JSON.stringify({installed:s.installed,running:s.running,version_target:s.version_target,process_detail:s.process_detail,checked_at:s.checked_at,jobs:s.jobs},null,2);$('blenderPaths').textContent=JSON.stringify({paths:s.paths,counts:s.counts},null,2);$('blenderActions').textContent=(s.actions||[]).map(x=>x.time+' · '+x.message).join('\n')||'Nenhuma ação registrada.';$('blenderNodesList').textContent=blenderItems(s.inventory.nodes);$('blenderTexturesList').textContent=blenderItems(s.inventory.textures);$('blenderRigsList').textContent=blenderItems(s.inventory.rigs);$('blenderClothesList').textContent=blenderItems(s.inventory.clothes);const jobs=s.jobs||[];if(jobs.length)$('blenderRenderLog').textContent=JSON.stringify(jobs[jobs.length-1],null,2)}async function refreshBlender(){if(!key){$('blenderState').textContent='Conecte o token primeiro.';return}try{renderBlender(await api('/api/blender/status'))}catch(e){$('blenderState').textContent='Falha: '+e.message}}async function blenderAction(path){try{const r=await api(path,{method:'POST'});$('blenderActions').textContent=JSON.stringify(r,null,2);setTimeout(refreshBlender,900)}catch(e){$('blenderActions').textContent='Falha: '+e.message}}function toggleBlenderMonitor(){if(blenderTimer){clearInterval(blenderTimer);blenderTimer=null;$('blenderMonitor').textContent='MONITOR: LIGAR'}else{refreshBlender();blenderTimer=setInterval(refreshBlender,5000);$('blenderMonitor').textContent='MONITOR: LIGADO'}}document.querySelectorAll('[data-blender-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-blender-tab]').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.blender-panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.blenderTab).classList.add('active')});document.querySelectorAll('[data-blender-open]').forEach(b=>b.onclick=()=>blenderAction('/api/blender/open?target='+encodeURIComponent(b.dataset.blenderOpen)));$('blenderSetup').onclick=()=>blenderAction('/api/blender/setup');$('blenderLaunch').onclick=()=>blenderAction('/api/blender/launch');$('blenderRefresh').onclick=refreshBlender;$('blenderMonitor').onclick=toggleBlenderMonitor;$('blenderStartRender').onclick=async()=>{const body={blend_file:$('blenderBlendFile').value.trim(),mode:$('blenderRenderMode').value,frame:Number($('blenderFrame').value||1),output_name:$('blenderOutputName').value.trim()||'aurion_render'};$('blenderRenderLog').textContent='Iniciando render...';try{const job=await api('/api/blender/render',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('blenderRenderLog').textContent=JSON.stringify(job,null,2);setTimeout(refreshBlender,1000)}catch(e){$('blenderRenderLog').textContent='Falha: '+e.message}};async function loadVault(){try{const r=await api('/api/manual-vault');$('vaultResults').textContent=JSON.stringify(r,null,2)}catch(e){$('vaultResults').textContent='Falha: '+e.message}}async function uploadVault(){const files=Array.from($('vaultFiles').files||[]);if(!files.length){$('vaultResults').textContent='Selecione pelo menos um arquivo.';return}if(!key){$('vaultResults').textContent='Conecte o token primeiro.';return}$('vaultUpload').disabled=true;const out=[];try{for(const file of files){try{out.push(await api('/api/manual-vault/import?filename='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Aurion-File-Size':String(file.size)},body:file}))}catch(e){out.push({name:file.name,error:e.message})}$('vaultResults').textContent=JSON.stringify(out,null,2)}}finally{$('vaultUpload').disabled=false}}$('vaultUpload').onclick=uploadVault;$('vaultRefresh').onclick=loadVault;$('inventoryButton').onclick=async()=>{try{$('inventory').textContent=JSON.stringify(await api('/api/inventory'),null,2)}catch(e){$('inventory').textContent='Falha: '+e.message}};$('chat').onsubmit=async e=>{e.preventDefault();const text=$('message').value.trim();if(!text)return;if(!key){note('Conecte o token primeiro.');return}bubble(text,true);$('message').value='';$('send').disabled=true;const waiting=bubble('Aguardando resposta do agente...');try{const r=await api('/api/prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,device_id:'portal-pc',moving:false})});waiting.textContent=r.answer||('Estado: '+r.status);if(r.status!=='completed')waiting.classList.add('error')}catch(err){waiting.textContent='Erro real: '+err.message;waiting.classList.add('error')}finally{$('send').disabled=false}};status();
</script></body></html>'''
